import React, { Component } from 'react';
import { CButton, CInput } from '@coreui/react';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import { Table } from 'react-bootstrap';

const FILE_NAME = "ListSubPrograms.js";

class ListSubPrograms extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            subPrograms: [],
            programs: [],
            page: 1,
            size: 20,
            totalPages: 0,
            totalElements: 0,
            search: '',
            programIdFilter: '',
            programTypeFilter: '',
        };
    }

    componentDidMount() {
        document.title = "Sub-Programs";
        this.fetchPrograms();
        this.fetchSubPrograms();
    }

    fetchPrograms() {
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list';
        const reqData = { page: 1, size: 100 };

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => response.status === 200 ? response.json() : null)
        .then(result => {
            if (result && result.data) {
                this.setState({ programs: result.data.content || [] });
            }
        })
        .catch(error => Logger(FILE_NAME, "fetchPrograms", "ERROR", "error", error));
    }

    fetchSubPrograms = () => {
        const { page, size, search, programIdFilter } = this.state;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list';

        const reqData = {
            page,
            size,
            search: search.length >= 2 ? search : null,
            programId: programIdFilter ? Number(programIdFilter) : null,
        };

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchSubPrograms", "SUCCESS", "result", result);
            const pageData = result.data;
            this.setState({
                isLoaded: true,
                subPrograms: pageData.content || [],
                totalPages: pageData.totalPages || 0,
                totalElements: pageData.totalElements || 0,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchSubPrograms", "ERROR", "error", error);
            this.setState({ isLoaded: true });
        });
    }

    handleSearchSubmit = (e) => {
        e.preventDefault();
        this.setState({ page: 1 }, this.fetchSubPrograms);
    }

    goToPage = (newPage) => {
        this.setState({ page: newPage }, this.fetchSubPrograms);
    }

    getProgramName = (programId) => {
        const prog = this.state.programs.find(p => p.id === programId);
        return prog ? prog.name : programId;
    }

    getProgramType = (programId) => {
        const prog = this.state.programs.find(p => p.id === programId);
        return prog ? prog.type : null;
    }

    getFilteredPrograms = () => {
        const { programs, programTypeFilter } = this.state;
        if (!programTypeFilter) return programs;
        return programs.filter(p => p.type === programTypeFilter);
    }

    getFilteredSubPrograms = () => {
        const { subPrograms, programTypeFilter } = this.state;
        if (!programTypeFilter) return subPrograms;
        return subPrograms.filter(sp => this.getProgramType(sp.programId) === programTypeFilter);
    }

    render() {
        const { isLoaded, programs, page, totalPages, totalElements, search, programIdFilter, programTypeFilter } = this.state;
        const filteredPrograms = this.getFilteredPrograms();
        const filteredSubPrograms = this.getFilteredSubPrograms();

        if (!isLoaded) return <Loading />;

        return (
            <div>
                <a href="#/program" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Program Home</CButton>
                </a>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>📦 Sub-Programs ({totalElements})</h2>
                    <a href="#/sub-program/create">
                        <CButton color="success">+ Create Sub-Program</CButton>
                    </a>
                </div>

                {/* Search + Filter */}
                <form onSubmit={this.handleSearchSubmit} style={{ display: 'flex', gap: '8px', marginBottom: '16px', flexWrap: 'wrap' }}>
                    <CInput
                        placeholder="Search by name..."
                        value={search}
                        onChange={(e) => this.setState({ search: e.target.value })}
                        style={{ maxWidth: '250px' }}
                    />
                    <select
                        value={programTypeFilter}
                        onChange={(e) => this.setState({ programTypeFilter: e.target.value, programIdFilter: '', page: 1 }, this.fetchSubPrograms)}
                        style={{ padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px' }}
                    >
                        <option value="">All Types</option>
                        <option value="WORK">WORK</option>
                        <option value="PERSONAL">PERSONAL</option>
                    </select>
                    <select
                        value={programIdFilter}
                        onChange={(e) => this.setState({ programIdFilter: e.target.value, page: 1 }, this.fetchSubPrograms)}
                        style={{ padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px' }}
                    >
                        <option value="">All Programs</option>
                        {filteredPrograms.map(p => (
                            <option key={p.id} value={p.id}>{p.name}</option>
                        ))}
                    </select>
                    <CButton color="primary" type="submit">Search</CButton>
                    {(search || programIdFilter || programTypeFilter) && (
                        <CButton color="secondary" onClick={() => this.setState({ search: '', programIdFilter: '', programTypeFilter: '', page: 1 }, this.fetchSubPrograms)}>Clear</CButton>
                    )}
                </form>

                {/* Table */}
                <Table striped bordered hover style={{ width: '100%' }}>
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Program</th>
                            <th>Name</th>
                            <th>Description</th>
                            <th>Created (yyyy-mm-dd)</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredSubPrograms.length === 0 ? (
                            <tr><td colSpan="6" style={{ textAlign: 'center', color: '#888' }}>No sub-programs found</td></tr>
                        ) : (
                            filteredSubPrograms.map(sp => (
                                <tr key={'sp-' + sp.id}>
                                    <td>{sp.id}</td>
                                    <td>{this.getProgramName(sp.programId)}</td>
                                    <td><strong>{sp.name}</strong></td>
                                    <td style={{ color: '#666', maxWidth: '200px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{sp.description || '—'}</td>
                                    <td>{sp.createdOn ? new Date(sp.createdOn).toISOString().split('T')[0] : '—'}</td>
                                    <td>
                                        <CButton color="info" size="sm" onClick={() => window.open('#/sub-program/' + sp.id, '_blank')}>
                                            View ↗
                                        </CButton>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </Table>

                {/* Pagination */}
                {totalPages > 1 && (
                    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '12px', marginTop: '16px' }}>
                        <CButton color="secondary" size="sm" disabled={page <= 1} onClick={() => this.goToPage(page - 1)}>← Prev</CButton>
                        <span>Page {page} of {totalPages}</span>
                        <CButton color="secondary" size="sm" disabled={page >= totalPages} onClick={() => this.goToPage(page + 1)}>Next →</CButton>
                    </div>
                )}
            </div>
        );
    }
}

export default ListSubPrograms;
